import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type DashboardAnimationProps = Record<string, any>;

// Helper for rendering icons based on enum
const IconWrapper = ({
  name,
  color,
  size = 24,
}: {
  name: string;
  color: string;
  size?: number;
}) => {
  const commonProps = {
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: color,
    strokeWidth: 2,
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
    style: { display: "block" },
  };

  switch (name) {
    case "music":
      return (
        <svg {...commonProps}>
          <path d="M9 18V5l12-2v13" />
          <circle cx="6" cy="18" r="3" />
          <circle cx="18" cy="16" r="3" />
        </svg>
      );
    case "mic":
      return (
        <svg {...commonProps}>
          <path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z" />
          <path d="M19 10v2a7 7 0 0 1-14 0v-2" />
          <line x1="12" x2="12" y1="19" y2="22" />
        </svg>
      );
    case "grid":
      return (
        <svg {...commonProps}>
          <rect width="7" height="7" x="3" y="3" rx="1" />
          <rect width="7" height="7" x="14" y="3" rx="1" />
          <rect width="7" height="7" x="14" y="14" rx="1" />
          <rect width="7" height="7" x="3" y="14" rx="1" />
        </svg>
      );
    case "broadcast":
      return (
        <svg {...commonProps}>
          <circle cx="12" cy="12" r="2" />
          <path d="M16.24 7.76a6 6 0 0 1 0 8.49m-8.48 0a6 6 0 0 1 0-8.49m11.31-2.82a10 10 0 0 1 0 14.14m-14.14 0a10 10 0 0 1 0-14.14" />
        </svg>
      );
    case "star":
      return (
        <svg {...commonProps}>
          <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
        </svg>
      );
    case "check":
      return (
        <svg {...commonProps}>
          <path d="M20 6 9 17l-5-5" />
        </svg>
      );
    case "flame":
      return (
        <svg {...commonProps} fill={color} stroke="none">
          <path d="M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z" />
        </svg>
      );
    default:
      return null;
  }
};

const DashboardAnimation: React.FC<DashboardAnimationProps> = ({
  backgroundColor = "#121b16",
  transparentBackground = false,
  durationInSeconds = 5,
  accentColor = "#6bed9d",
  panelColor = "#2b3d33",
  cardColor = "#465f50",
  textColorPrimary = "#ffffff",
  textColorSecondary = "#9eb2a4",
  tabs = [
    { label: "Songs", count: 3, icon: "music", isActive: true },
    { label: "Shows", count: 3, icon: "mic", isActive: false },
    { label: "Brand Collabs", count: 2, icon: "grid", isActive: false },
    { label: "Podcast", count: 1, icon: "broadcast", isActive: false },
    { label: "Artist Dev", count: 1, icon: "star", isActive: false },
  ],
  tracks = [
    {
      title: '"Silk Road" — Live Set',
      subtitle: "Apex Sound · 2024",
      score: 91,
      tags: ["Apex Sound"],
    },
    {
      title: '"Late Arrival" — Original',
      subtitle: "Self-released · 280K streams",
      score: 88,
      tags: ["Nova Beats", "Waveform Co."],
    },
    {
      title: '"Pressure Drop" — Remix',
      subtitle: "Orbital Records · 2023",
      score: 85,
      tags: ["Orbital Records"],
    },
  ],
}) => {
  useFontLoader(["Poppins"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const actualBgColor = transparentBackground
    ? "transparent"
    : backgroundColor;

  // Global Container Animation
  const containerScale = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  
  const containerOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: actualBgColor,
        fontFamily: "Poppins",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "60px",
      }}
    >
      <div
        style={{
          width: "100%",
          maxWidth: "1800px",
          height: "100%",
          backgroundColor: panelColor,
          borderRadius: "32px",
          border: `2px solid ${accentColor}80`, // Subtle bright border
          display: "flex",
          flexDirection: "column",
          overflow: "hidden",
          opacity: containerOpacity,
          transform: `scale(${interpolate(containerScale, [0, 1], [0.95, 1])})`,
          boxShadow: "0 24px 64px rgba(0,0,0,0.5), inset 0 2px 0 rgba(255,255,255,0.05)",
        }}
      >
        {/* Header / Tabs */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            padding: "0 40px",
            borderBottom: `2px solid ${cardColor}`,
            height: "100px",
            gap: "48px",
          }}
        >
          {tabs.map((tab, idx) => {
            const tabDelay = idx * 5;
            const tabFrame = Math.max(0, frame - tabDelay);
            const tabY = interpolate(tabFrame, [0, 20], [-20, 0], {
              extrapolateRight: "clamp",
            });
            const tabOp = interpolate(tabFrame, [0, 20], [0, 1], {
              extrapolateRight: "clamp",
            });

            const color = tab.isActive ? textColorPrimary : textColorSecondary;
            const badgeBg = tab.isActive ? `${accentColor}30` : `${cardColor}80`;
            const badgeColor = tab.isActive ? accentColor : textColorPrimary;

            return (
              <div
                key={tab.label}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "12px",
                  height: "100%",
                  position: "relative",
                  cursor: "pointer",
                  opacity: tabOp,
                  transform: `translateY(${tabY}px)`,
                }}
              >
                <IconWrapper name={tab.icon} color={color} size={24} />
                <span
                  style={{
                    color,
                    fontSize: "22px",
                    fontWeight: tab.isActive ? 600 : 500,
                  }}
                >
                  {tab.label}
                </span>
                <div
                  style={{
                    backgroundColor: badgeBg,
                    color: badgeColor,
                    padding: "2px 12px",
                    borderRadius: "20px",
                    fontSize: "16px",
                    fontWeight: 600,
                  }}
                >
                  {tab.count}
                </div>

                {tab.isActive && (
                  <div
                    style={{
                      position: "absolute",
                      bottom: "-2px",
                      left: "-20px", // Extend slightly beyond text
                      right: "-20px",
                      height: "3px",
                      backgroundColor: accentColor,
                      borderRadius: "3px",
                      transformOrigin: "left center",
                      transform: `scaleX(${spring({
                        frame: Math.max(0, frame - 15),
                        fps,
                        config: { damping: 14 },
                      })})`,
                    }}
                  />
                )}
              </div>
            );
          })}
        </div>

        {/* Tracks List */}
        <div
          style={{
            flex: 1,
            padding: "40px",
            display: "flex",
            flexDirection: "column",
            gap: "24px",
            overflow: "hidden",
          }}
        >
          {tracks.map((track, idx) => {
            const trackDelay = 20 + idx * 8;
            const trackFrame = Math.max(0, frame - trackDelay);
            
            const trackSpring = spring({
              frame: trackFrame,
              fps,
              config: { damping: 14, mass: 0.8 },
            });

            const trackY = interpolate(trackSpring, [0, 1], [40, 0]);
            const trackOp = interpolate(trackFrame, [0, 15], [0, 1], {
              extrapolateRight: "clamp",
            });

            return (
              <div
                key={track.title}
                style={{
                  backgroundColor: cardColor,
                  borderRadius: "20px",
                  padding: "24px",
                  display: "flex",
                  alignItems: "center",
                  gap: "24px",
                  opacity: trackOp,
                  transform: `translateY(${trackY}px)`,
                  border: "1px solid rgba(255,255,255,0.05)",
                  boxShadow: "0 8px 32px rgba(0,0,0,0.15)",
                }}
              >
                {/* Icon Box */}
                <div
                  style={{
                    width: "80px",
                    height: "80px",
                    borderRadius: "16px",
                    backgroundColor: "rgba(255,255,255,0.05)",
                    border: "1px solid rgba(255,255,255,0.1)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    flexShrink: 0,
                  }}
                >
                  <IconWrapper name="music" color={accentColor} size={32} />
                </div>

                {/* Content */}
                <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: "12px" }}>
                  <div style={{ display: "flex", flexDirection: "column", gap: "4px" }}>
                    <h2
                      style={{
                        margin: 0,
                        color: textColorPrimary,
                        fontSize: "28px",
                        fontWeight: 600,
                        letterSpacing: "-0.5px",
                      }}
                    >
                      {track.title}
                    </h2>
                    <p
                      style={{
                        margin: 0,
                        color: textColorSecondary,
                        fontSize: "20px",
                        fontWeight: 400,
                      }}
                    >
                      {track.subtitle}
                    </p>
                  </div>

                  {/* Tags */}
                  <div style={{ display: "flex", gap: "12px" }}>
                    {track.tags.map((tag, tagIdx) => {
                      const tagDelay = trackDelay + 10 + tagIdx * 5;
                      const tagFrame = Math.max(0, frame - tagDelay);
                      const tagScale = spring({
                        frame: tagFrame,
                        fps,
                        config: { damping: 12 },
                      });

                      return (
                        <div
                          key={tag}
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: "8px",
                            padding: "6px 16px",
                            backgroundColor: "rgba(255,255,255,0.08)",
                            border: "1px solid rgba(255,255,255,0.15)",
                            borderRadius: "20px",
                            transform: `scale(${tagScale})`,
                            opacity: interpolate(tagFrame, [0, 5], [0, 1], {
                              extrapolateRight: "clamp",
                            }),
                          }}
                        >
                          <IconWrapper name="check" color={accentColor} size={16} />
                          <span
                            style={{
                              color: "#c3d6cb",
                              fontSize: "16px",
                              fontWeight: 500,
                            }}
                          >
                            {tag}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                </div>

                {/* Score */}
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "8px",
                    paddingRight: "16px",
                    transform: `scale(${spring({
                        frame: Math.max(0, trackFrame - 10),
                        fps,
                        config: { damping: 10, mass: 0.5 }
                    })})`
                  }}
                >
                  <IconWrapper name="flame" color={accentColor} size={28} />
                  <span
                    style={{
                      color: accentColor,
                      fontSize: "28px",
                      fontWeight: 700,
                    }}
                  >
                    {track.score}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DashboardAnimation;